before:
export async function collect(list) {
  return (await list(1)).items;
}

after:
export async function collect(list) {
  const items = [];
  let page = 1;
  let result;
  do {
    result = await list(page);
    items.push(...result.items);
    page = result.next;
  } while (result.next === null);
  return items;
}

